import { chromium } from 'playwright';
import fs from 'node:fs/promises';

const BASE = process.env.XRAI_URL || 'https://jt5d.github.io/xrai-agent/';
const EXPECTED_VERSION = process.env.XRAI_VERSION || '0.3.3';
const outDir = process.env.XRAI_E2E_OUT || 'xrai-e2e-artifacts';
await fs.mkdir(outDir,{recursive:true});
const browser=await chromium.launch({headless:true});
const context=await browser.newContext({viewport:{width:1512,height:982},serviceWorkers:'allow'});
const page=await context.newPage();
const consoleErrors=[],badRequests=[],githubRequests=[];
page.on('console',m=>{if(m.type()==='error')consoleErrors.push(m.text())});
page.on('pageerror',e=>consoleErrors.push(`pageerror: ${e.message}`));
page.on('request',r=>{const u=r.url();if(u.includes('api.github.com/repos/'))githubRequests.push(u);if(/api\.github\.com\/repos\/(filesystem\/repository|api\.github\.com\/repos)/i.test(u))badRequests.push(u)});
page.on('response',r=>{const u=r.url();if(r.status()>=400&&/jt5d\.github\.io\/xrai-agent|api\.github\.com|raw\.githubusercontent\.com|webcontainer|jsdelivr/i.test(u))consoleErrors.push(`HTTP ${r.status()} ${u}`)});
const screenshot=n=>page.screenshot({path:`${outDir}/${n}.png`,fullPage:false});
async function waitForApp(){await page.waitForSelector('#chatForm',{timeout:30000});await page.waitForFunction(v=>document.body.innerText.includes(v),EXPECTED_VERSION,{timeout:30000})}
async function waitForRunDone(timeout=300000){await page.waitForFunction(()=>{const b=document.querySelector('#runButton'),p=document.querySelector('#progressValue')?.textContent?.trim()||'',s=document.querySelector('#status')?.textContent||'';return b&&!b.disabled&&(p==='100%'||/error|failed|timeout|interrupted/i.test(s))},null,{timeout});await page.waitForTimeout(700)}
async function submit(t){await page.locator('#task').fill(t);await page.locator('#runButton').click()}
try{
  await page.goto(`${BASE}?e2e=${Date.now()}`,{waitUntil:'domcontentloaded',timeout:60000});await waitForApp();await page.waitForTimeout(1200);if(!await page.evaluate(()=>navigator.serviceWorker?.controller!=null)){await page.reload({waitUntil:'domcontentloaded'});await waitForApp()}
  await page.evaluate(()=>{localStorage.removeItem('xrai-ui-v4');localStorage.setItem('xrai-ui-v3',JSON.stringify({version:3,view:'workspace',lastTask:'review repo, fix any failed tests, verify & explain',runStatus:'error',statusText:'GitHub request failed (404) for https://api.github.com/repos/filesystem/repository',messages:[{role:'user',text:'review repo, fix any failed tests, verify & explain'},{role:'agent',text:'This task requires filesystem/repository and test execution. The public GitHub Pages runtime does not have those capabilities, so I stopped rather than pretending to inspect or modify a repo. Open Runtime and use the local execution host.'}],events:[],result:{output:'GitHub request failed (404) for https://api.github.com/repos/api.github.com/repos'},options:{workspace:'.',maxDepth:2,maxChildren:2,retries:1}}))});
  await page.reload({waitUntil:'domcontentloaded'});await waitForApp();await page.waitForTimeout(800);const stale=await page.locator('body').innerText();if(/public GitHub Pages runtime does not have those capabilities|repos\/filesystem\/repository|repos\/api\.github\.com\/repos/i.test(stale))throw new Error('Stale failure state survived migration.');await screenshot('01-clean-after-migration');
  await submit('review repo, fix any failed tests, verify & explain');await page.waitForFunction(()=>document.querySelector('#currentTask')?.textContent?.includes('review repo'),null,{timeout:10000});await page.waitForFunction(()=>document.body.innerText.includes('JT5D/xrai-agent')||document.body.innerText.includes('Inspecting public repo'),null,{timeout:30000});await waitForRunDone();await screenshot('02-repo-run-complete');
  const body=await page.locator('body').innerText();if(badRequests.length)throw new Error(`Bogus GitHub requests: ${badRequests.join(', ')}`);if(!githubRequests.some(u=>/api\.github\.com\/repos\/JT5D\/xrai-agent(?:$|\/)/i.test(u)))throw new Error('No real JT5D/xrai-agent GitHub API request observed.');if(!/PASS|verified|verification|tests?/i.test(body))throw new Error('No rendered verification evidence.');
  const before=await page.locator('#messages').innerText();await page.reload({waitUntil:'domcontentloaded'});await waitForApp();await page.waitForTimeout(800);const after=await page.locator('#messages').innerText();if(!after.includes('review repo')||after.length<Math.min(120,before.length/2))throw new Error('Completed result did not survive reload.');await screenshot('03-after-reload');
  const githubCount=githubRequests.length;await submit('is it fixed?');await page.waitForTimeout(2500);const follow=await page.locator('#messages').innerText();if(/what ["“]?it["”]? refers to|need more context/i.test(follow))throw new Error('Follow-up lost prior run context.');if(githubRequests.length!==githubCount)throw new Error('Vague follow-up incorrectly started another repo execution.');if(badRequests.length)throw new Error(`Bogus GitHub requests after follow-up: ${badRequests.join(', ')}`);await screenshot('04-followup-context');
  const errors=consoleErrors.filter(x=>!/favicon\.ico/i.test(x));await fs.writeFile(`${outDir}/console-errors.txt`,errors.join('\n'));await fs.writeFile(`${outDir}/github-requests.txt`,githubRequests.join('\n'));if(errors.length)throw new Error(`Relevant browser/network errors:\n${errors.join('\n')}`);console.log('XRAI live E2E PASS');console.log(`GitHub requests observed: ${githubRequests.length}`);
}catch(e){await screenshot('99-failure').catch(()=>{});await fs.writeFile(`${outDir}/failure.txt`,String(e?.stack||e)).catch(()=>{});await fs.writeFile(`${outDir}/console-errors.txt`,consoleErrors.join('\n')).catch(()=>{});await fs.writeFile(`${outDir}/github-requests.txt`,githubRequests.join('\n')).catch(()=>{});console.error(e);process.exitCode=1}finally{await browser.close()}
